#!/usr/bin/env node
/* generated by tools/gen-manifest.mjs -- run: node tools/gen-manifest.mjs (from web/ root) */
import fs from "node:fs";
import path from "node:path";
import url from "node:url";

const WEB_ROOT = path.resolve(path.dirname(url.fileURLToPath(import.meta.url)), "..");
const LUA_ROOT = path.join(WEB_ROOT, "lua");
const OUT_FILE = path.join(WEB_ROOT, "js", "manifest.js");
const CHARSET_FILE = path.join(WEB_ROOT, "tools", "tmp", "charset.txt");

// ---------- collect lua files ----------
function collectLua(dir) {
  const out = [];
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) out.push(...collectLua(p));
    else if (e.name.endsWith(".lua")) out.push(p);
  }
  return out.sort();
}
const luaFiles = collectLua(LUA_ROOT);

// ---------- asset scanning ----------
// Lua code references assets WITHOUT the "assets/" prefix (see UISkin.lua header comment).
// We scan string literals for image/ audio/ Fonts/ paths, normalize to web-root-relative
// "assets/..." form, and dedupe. Dynamic concatenations in the codebase resolve to
// values that already appear as literals (e.g. hero.id .. "_portrait.png" -> male/female).
const ASSET_RE = /"((?:image|audio|Fonts)\/[^"\\]+)"/g;
const found = new Set();
// The independent art preview ships before the summoner's gameplay integration.
// Preload its PNGs only once a runtime module actually consumes the atlas.
const fufuArtUsed = luaFiles.some(f => path.basename(f) !== "FufuArt.lua"
  && !f.includes(`${path.sep}tests${path.sep}`)
  && /require\s*\(\s*["']FufuArt["']\s*\)/.test(fs.readFileSync(f, "utf8")));
for (const f of luaFiles) {
  if (path.basename(f) === "FufuArt.lua" && !fufuArtUsed) continue;
  const text = fs.readFileSync(f, "utf8");
  let m;
  while ((m = ASSET_RE.exec(text)) !== null) {
    if (m[1].endsWith("/")) continue; // dynamic-concat prefix literal, e.g. "image/generated/" in tests/VisualScaleRules.lua
    found.add(m[1]);
  }
}
// Dynamic patterns audited by hand (tests/VisualScaleRules.lua:28-29):
//   "image/generated/" .. hero.id .. "_portrait.png" -> male_portrait/female_portrait
//   "image/generated/" .. hero.id .. "_battle.png"   -> male_battle/female_battle
// All four already exist as literals in Heroes.lua; nothing to add manually.

const images = [...found].filter((p) => p.startsWith("image/")).sort().map((p) => "assets/" + p);
const audio = [...found].filter((p) => p.startsWith("audio/")).sort().map((p) => "assets/" + p);
const fontsRaw = [...found].filter((p) => p.startsWith("Fonts/")).sort().map((p) => "assets/" + p);
// index.html only loads the subset files generated by tools/subset-fonts.py
const fonts = fontsRaw.map((p) => p.replace(/\.ttf$/, ".subset.ttf"));

// ---------- lua sources ----------
const luaSources = {};
for (const f of luaFiles) {
  const rel = path.relative(LUA_ROOT, f).replace(/\\/g, "/").replace(/\.lua$/, "");
  const key = rel.replace("/", "."); // "main", "Game", ..., "tests.Smoke"
  luaSources[key] = fs.readFileSync(f, "utf8");
}

// ---------- fonts block (keys mirror UISkin.lua weights) ----------
const FONT_KEY = {
  "assets/Fonts/FusionPixel-12px-Prop-zh_hans.subset.ttf": "pixel",
  "assets/Fonts/FusionPixel-12px-Prop-zh_hans-Bold.subset.ttf": "pixelBold",
  "assets/Fonts/FusionPixel-12px-Mono-zh_hans.subset.ttf": "pixelMono",
};
const fontsBlock = {};
for (const src of fonts) {
  const key = FONT_KEY[src];
  if (!key) throw new Error("unmapped font: " + src);
  fontsBlock[key] = { family: key === "pixelMono" ? "FusionPixelMono" : "FusionPixel", src };
}

// ---------- charset for subsetting (also written for tools/subset-fonts.py) ----------
const charset = new Set();
for (const text of Object.values(luaSources)) for (const ch of text) charset.add(ch);
for (let c = 0x20; c <= 0x7e; c++) charset.add(String.fromCodePoint(c)); // ASCII printable
const EXTRA_PUNCT =
  "\uFF0C\u3002\uFF01\uFF1F\uFF1A\uFF1B\u300C\u300D\u300E\u300F\u3001\u00B7\u2026\u2014\uFF0D+" +
  "%\uFF08\uFF09\u3010\u3011\u300A\u300B\u2018\u2019\u201C\u201D\uFF5E\u00A5\u00D7\u00F7" +
  "\u2190\u2191\u2192\u2193\u2605\u2606\u25CF\u25CB\u25A0\u25A1\u25B2\u25BC\u2665\u2660\u2666\u2663";
for (const ch of EXTRA_PUNCT) charset.add(ch);
fs.mkdirSync(path.dirname(CHARSET_FILE), { recursive: true });
fs.writeFileSync(CHARSET_FILE, [...charset].join(""));

// ---------- emit ----------
const manifest = {
  assets: { images, audio, fonts },
  luaSources,
  fonts: fontsBlock,
};
const js =
  "/* generated by tools/gen-manifest.mjs */\n" +
  "(function () {\n" +
  '  window.DSH = window.DSH || {};\n' +
  "  window.DSH.MANIFEST = " + JSON.stringify(manifest, null, 1) + ";\n" +
  "})();\n";
fs.mkdirSync(path.dirname(OUT_FILE), { recursive: true });
fs.writeFileSync(OUT_FILE, js);

console.log("lua files:", luaFiles.length);
console.log("images:", images.length, "| audio:", audio.length, "| fonts:", fonts.length, "| total:", images.length + audio.length + fonts.length);
console.log("charset:", charset.size, "chars ->", path.relative(WEB_ROOT, CHARSET_FILE));
console.log("manifest ->", path.relative(WEB_ROOT, OUT_FILE), js.length, "bytes");
